public static class WaterHelper{public static void InitLiquidContainerItem(){}public static bool IsFaucet(GameItem i){return i.faucet;}public static void Init(GameItem item){item.onThisTargetItemFunc=(container,target)=>{if(target!=null&&target.faucet&&NetworkUpgrade.Unlocked)AddWater(container,1,9999999,true,9102,9102);};FaucetRules.Wrap(item);}public static void AddWater(GameItem target,int grade,int add,bool range,int low,int high){FaucetOutput.Prefix(target,ref grade,ref add,ref range,ref low,ref high);long room=target.capacity-target.water-target.other;long n=add==-1?room:Math.Min(add,room);if(n<=0)return;long pure=(n*(range?low:9102)+9999)/10000;target.water+=pure;target.other+=n-pure;}}
class Test{static int n;static void C(bool b,string label){n++;if(!b)throw new Exception(label);}static GameItem Container(long capacity,long water=0,long other=0){var c=new GameItem{capacity=capacity,water=water,other=other,name="container"};WaterHelper.Init(c);return c;}static void Main(){var entry=new Entry();entry.OnEnable();var faucet=new GameItem{faucet=true};foreach(long cap in new long[]{1000,1000000,50000000,500000000,2000000000}){var c=Container(cap);c.onThisTargetItemFunc(c,faucet);C(c.water==cap&&c.other==0,"empty container filled pure to exact capacity "+cap);C(FaucetRules.Recipient==null,"no scope leaks");}var half=Container(50000000,18000000);half.onThisTargetItemFunc(half,faucet);C(half.water==50000000&&half.other==0,"partial pure container fills remainder");var mixed=Container(50000000,9000000,1000000);mixed.onThisTargetItemFunc(mixed,faucet);C(mixed.water==49000000&&mixed.other==1000000,"existing chemical content is preserved rather than erased");var full=Container(10,9,1);full.onThisTargetItemFunc(full,faucet);C(full.water==9&&full.other==1,"full container unchanged");var untouched=Container(50000000);WaterHelper.AddWater(untouched,1,9999999,true,9102,9102);C(untouched.other>0&&untouched.water+untouched.other==9999999,"nonfaucet water source unchanged");var throws=new GameItem{onThisTargetItemFunc=(x,y)=>{throw new InvalidOperationException();}};FaucetRules.Wrap(throws);try{throws.onThisTargetItemFunc(throws,faucet);}catch(InvalidOperationException){}C(FaucetRules.Recipient==null,"exception restores scoped context");var elem=new GameItemElement{faucet=true,name="水龙头"};bool visible=false;FaucetTooltipVisible.Postfix(elem,ref visible);C(visible,"standalone native tooltip becomes visible without ItemDetails");RichText tip=null;FaucetTooltip.Postfix(elem,ref tip);C(tip.Text.Contains("出水水质：纯水")&&tip.Text.Contains("100.00%")&&!tip.Text.Contains("铁锈水"),"front-end quality and composition match source");FaucetAdvancedTooltip.Postfix(elem,ref tip);C(tip.Text.Contains("100.00%"),"advanced view agrees");var normal=new GameItemElement{faucet=false};var original=new RichText{Text="original"};tip=original;FaucetTooltip.Postfix(normal,ref tip);C(Object.ReferenceEquals(tip,original),"unrelated item tooltip untouched");NetworkUpgrade.Unlocked=false;var locked=Container(100);locked.onThisTargetItemFunc(locked,faucet);C(locked.water==0,"native unlock requirement retained");tip=null;FaucetTooltip.Postfix(elem,ref tip);C(tip.Text.Contains("水管尚未接通"),"locked tap is not falsely shown as available");NetworkUpgrade.Unlocked=true;entry.OnDisable();var disabled=Container(50000000);disabled.onThisTargetItemFunc(disabled,faucet);C(disabled.other>0&&disabled.water+disabled.other==9999999,"disable restores native output");entry.OnEnable();foreach(string language in new[]{"en","zh-Hant","zh"}){LocHelper.Locale=language;L.LanguageOverride="Auto";NetworkUpgrade.Unlocked=true;var localized=FaucetRules.Tooltip(elem).Text;C(localized.Contains(L.Text("quality"))&&localized.Contains("100.00%"),"localized quality and composition "+language);NetworkUpgrade.Unlocked=false;C(FaucetRules.Tooltip(elem).Text.Contains(L.Text("locked")),"localized supply-line requirement "+language);NetworkUpgrade.Unlocked=true;var localWater=Container(50000000);localWater.onThisTargetItemFunc(localWater,faucet);C(localWater.water==50000000&&localWater.other==0,"language cannot change actual pure output "+language);}L.LanguageOverride="繁體中文";LocHelper.Locale="en";C(FaucetRules.Tooltip(elem).Text.Contains("純水"),"manual traditional override while game is English");L.LanguageOverride="English";LocHelper.Locale="zh";C(FaucetRules.Tooltip(elem).Text.Contains("Output quality: pure water"),"manual English override while game is Chinese");Console.WriteLine(n+" standalone faucet output, limits, scope, existing contents, unlock, disable and frontend checks passed (native boundary mocked)");}}

